import{_ as t,o as n,c as o,a6 as a}from"./chunks/framework.CKIbuWFA.js";const f=JSON.parse('{"title":"Manage LIVE connections","description":"","frontmatter":{"title":"Manage LIVE connections","docId":"user.live.connections","translationKey":"user.live.connections","locale":"en","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"37f7274550d3010051ab456da2a2091b650e5e7aaaf30756b6695435bcfc08c7","translationRevision":"37f7274550d3010051ab456da2a2091b650e5e7aaaf30756b6695435bcfc08c7","order":10},"headers":[],"relativePath":"en/user/live/connections.md","filePath":"en/user/live/connections.md","lastUpdated":1794591482000}'),r={name:"en/user/live/connections.md"};function i(s,e,c,l,d,h){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="manage-live-connections" tabindex="-1">Manage LIVE connections <a class="header-anchor" href="#manage-live-connections" aria-label="Permalink to &quot;Manage LIVE connections {#manage-live-connections}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Goal and prerequisites {#goal-and-prerequisites}&quot;">​</a></h2><p>Connect to a specific creator, understand reconnection, and configure plugin servers independently. You need a working <a href="./../installation.html">desktop installation</a>, network access, and the creator&#39;s handle. Check <a href="./../requirements.html">requirements</a> before diagnosing operating system problems.</p><h2 id="connect-deliberately" tabindex="-1">Connect deliberately <a class="header-anchor" href="#connect-deliberately" aria-label="Permalink to &quot;Connect deliberately {#connect-deliberately}&quot;">​</a></h2><ol><li>Open <strong>Connections</strong>. Enter the handle, with or without <code>@</code>; a display name is not the same identifier.</li><li>Start with <strong>Use Cookie</strong> off. If TikTok requires an authorized session, enable it and enter the cookie only in the masked field. Cookies remain in memory; do not paste them into diagnostics or Cloud settings.</li><li>Leave <strong>Monitor and auto-connect</strong> off for a direct attempt, then select <strong>Connect</strong>. Read the status and any error before retrying.</li><li>Check <a href="./feed.html">Live feed</a> for the correct creator and a new event. A connected but quiet room may show no activity.</li><li>Use <strong>Reconnect</strong> for the same creator or <strong>Disconnect</strong> before changing creators. During a busy attempt, <strong>Cancel</strong> stops that attempt.</li></ol><p>After a successful direct connection, enable monitoring to wait for a creator to go live. Waiting and checking are distinct from being connected. Stop monitoring before editing a locked handle. Selecting a recent creator starts a connection; it is more than filling the input.</p><p>The explorer offers discovered rooms, but results can become stale. Refresh before assuming a room is still available. Plugin server connections in the lower panel configure their own services; a connected plugin does not establish TikTok or Cloud authentication.</p><h2 id="expected-result-and-status" tabindex="-1">Expected result and status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Expected result and status {#expected-result-and-status}&quot;">​</a></h2><p>Direct connections, monitoring and plugin connection controls are available. Reconnecting to the same creator preserves the current feed context; changing creator starts another context. Actual TikTok access depends on the upstream room and session, and is not guaranteed by a successful local test.</p><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recovery {#recovery}&quot;">​</a></h2><p>For offline rooms, verify that the creator is live. For session or rate-limit errors, follow the reported retry condition. Repeated reconnect clicks do not refresh authentication. Use <a href="./../preferences/troubleshooting.html">troubleshooting</a> to collect the failing component and time without exposing credentials.</p>',11)])])}const g=t(r,[["render",i]]);export{f as __pageData,g as default};
